window.PREP_COURSES = [
    {
        id: 'faang', title: 'FAANG Interview Preparation', price: 49, icon: 'route',
        summary: 'A practical 30/60/90-day preparation framework for coding, system design, behavioral rounds, and company-specific revision.',
        audience: 'Software engineers preparing for Google, Meta, Amazon, Apple, Netflix, and comparable product-company roles.',
        prerequisites: 'Comfort writing basic code in one language. For experienced roles, bring one project you can explain in depth.',
        outcomes: ['Choose a role-appropriate preparation plan', 'Diagnose coding and design weaknesses with evidence', 'Build truthful, specific behavioral stories', 'Run mocks and revise from a consistent scorecard'],
        plans: [
            ['30 days', 'Days 1-3: diagnostic and role scope. Days 4-14: weakest patterns with re-solves. Days 15-23: mixed coding and design mocks. Days 24-30: company alignment, behavioral practice, and recovery time. Best for candidates with an existing foundation.'],
            ['60 days', 'Weeks 1-2: language, arrays, hashing, and pointers. Weeks 3-4: trees, graphs, heaps, and binary search. Weeks 5-6: DP, design, and project depth. Weeks 7-8: mixed mocks and company-specific revision. Use the remaining days for weak areas and interview logistics.'],
            ['90 days', 'Weeks 1-4: fundamentals and repeatable patterns. Weeks 5-8: graphs, DP, testing, and design foundations. Weeks 9-10: role-specific depth. Weeks 11-12: mocks and story refinement. Final days: targeted review, recruiter confirmation, and rest.']
        ],
        lessons: [
            { id: 'scope', title: 'Choose the Role and Establish a Baseline',
              notes: ['Write down the target role, level, location, and team before choosing a question list. An entry-level SWE, senior backend engineer, and ML engineer do not need the same balance of coding, design, and domain depth.', 'Run one unseen coding problem, one design discussion if the role requires it, and one project walkthrough. Record where you needed help: understanding, algorithm choice, implementation, testing, or communication. A solved counter alone does not reveal readiness.'],
              qa: [['How do I know what the interview will cover?', 'Use the job description and current official hiring guidance, then ask the recruiter to confirm round types, tools, language restrictions, and level expectations. Public question lists are practice material, not a contract for your interview.'], ['Should I start with hard problems?', 'Not if medium problems still expose basic implementation or pattern gaps. Build reliable fundamentals first, then use harder problems to develop new reasoning rather than memorize answers.']],
              exercise: ['Create a two-week improvement plan from a failed sliding-window problem.', 'Identify whether the failure was recognizing the invariant, updating counts, or handling boundaries. Practice two targeted variants, re-solve without notes after several days, then test transfer on a new mixed problem. Measure independent correctness and explanation quality.'] },
            { id: 'coding-loop', title: 'A Repeatable Coding Interview Loop',
              notes: ['Clarify input constraints, output rules, mutation, and edge cases. State a simple correct baseline before optimizing. Explain the invariant that makes the optimized algorithm correct.', 'Implement in your chosen language without depending on autocomplete. Trace one normal example and at least two boundary cases, then analyze both time and auxiliary space. Separate output memory from working memory.'],
              qa: [['What if I cannot find the optimal algorithm immediately?', 'Explain a correct baseline and its bottleneck. Use constraints to decide whether sorting, a hash map, a monotone search space, or a dynamic-programming state can remove repeated work. Ask clarifying questions rather than silently guessing.'], ['How should I respond when the interviewer points out a bug?', 'Restate the failing case, identify the broken invariant, make the smallest correction, and rerun that case plus a neighboring one. Defending incorrect code wastes time; showing precise recovery demonstrates engineering judgment.']],
              exercise: ['Give a 45-minute mock structure without treating the timings as an employer rule.', 'Use roughly 5 minutes for clarification, 8 for approach and proof, 20 for implementation, 8 for tests and complexity, and 4 for follow-ups. Adjust to the actual interviewer and problem.'] },
            { id: 'patterns', title: 'Pattern Coverage and Spaced Revision',
              notes: ['Cover arrays and hashing, two pointers, sliding windows, stacks, binary search, linked structures, trees, graphs, heaps, intervals, backtracking, and dynamic programming. Learn the decision that selects a pattern, not just its code template.', 'A useful revision record includes the missed clue, invariant, complexity, edge case, and a next re-solve date. Try re-solves after about 2, 7, and 21 days, adjusting intervals to your recall rather than treating them as a guarantee.'],
              qa: [['When is a sliding window inappropriate?', 'When expanding or shrinking does not have a usable monotone effect on validity. For example, arbitrary negative numbers break the simple positive-sum window rule; prefix sums and frequency counts may be appropriate instead.'], ['How do I stop memorizing solutions?', 'Explain the invariant before coding, change a constraint, and solve a related unseen problem. If a small change breaks your approach, study why the algorithm worked before adding more problems to your count.']],
              exercise: ['Compare Subarray Sum Equals K with Minimum Size Subarray Sum for positive inputs.', 'The exact-sum problem with arbitrary integers needs counts of earlier prefix sums. The positive-input minimum-length problem supports a shrinking window because removing a positive value cannot increase the sum. The constraint, not the word subarray, determines the method.'] },
            { id: 'design', title: 'System Design for Your Experience Level',
              notes: ['Start with use cases, explicit non-goals, scale assumptions, and consistency or latency requirements. Define APIs and the data model, then walk one read and one write through the architecture.', 'Choose two or three deep dives from the requirements: contention, replication, caching, partitions, large objects, backpressure, or failure recovery. Explain how you would observe, test, and operate the design.'],
              qa: [['Should I draw every possible component?', 'No. Every component should address a stated requirement or bottleneck. A queue adds buffering and asynchronous failure modes; a cache adds invalidation and staleness. Explain why each is worth its cost.'], ['How do senior answers differ from junior answers?', 'Expectations vary, but experienced candidates should usually own ambiguity, prioritize trade-offs, explain failure boundaries, and connect capacity and operational decisions to the business. Confirm the target level instead of memorizing a generic architecture.']],
              exercise: ['Prepare a rate-limiter deep dive.', 'Specify the key and scope, limit semantics, burst allowance, token-bucket or window algorithm, atomic update boundary, regional behavior, and fail-open/fail-closed policy. Include a hot-key case and a partition case.'] },
            { id: 'company-tracks', title: 'Company-Aligned Preparation, Not Question Predictions',
              notes: ['Google: practice invariant-based reasoning and alternative approaches. Meta: practice clear implementations and product-oriented design, while confirming the current loop with the recruiter. Amazon: combine tested code and practical design with truthful Leadership Principle examples.', 'Apple: prioritize the specialization in the job description and implementation details. Netflix: connect role-specific technical decisions to operational judgment and business outcomes. Microsoft: practice problem solving, design, coding, and testing, adding AI/ML, networking, or distributed systems when the role calls for them.', 'For NVIDIA, add performance, memory, concurrency, or inference depth when relevant to the role. For Oracle cloud/database positions, add transactions, indexes, consistency, and recovery. These are editorial study tracks, not a verified record of questions asked or employer endorsements.'],
              qa: [['Can a company tag tell me what I will be asked?', 'No. Tags are useful for organizing practice, but interview content changes across teams, levels, regions, and time. Use official guidance and recruiter confirmation for scope, and use tagged questions to test transferable skills.'], ['How do I tailor the final week?', 'Allocate most revision to the actual role requirements and your mock failures. Keep a small mixed-problem set to avoid overfitting to tags. Review two role-relevant designs and several truthful stories rather than chasing an alleged last-minute leak.']],
              exercise: ['Compare a Microsoft storage role with an ML-serving role.', 'Both need sound coding and testing. The storage role may need replication, durability, networking, and tail-latency reasoning. The ML-serving role may need model versioning, batching, KV memory, evaluation, and cost controls. Confirm rather than assume the team-specific depth.'] },
            { id: 'behavioral', title: 'Truthful STAR Stories and Project Depth',
              notes: ['Prepare examples of ownership, a failure, a disagreement, ambiguity, customer impact, collaboration, and a difficult trade-off. Use situation and task briefly, spend most time on your own actions, then give the result and what you learned.', 'Only use metrics you can justify. Distinguish team achievements from your contribution and acknowledge uncertainty in estimates. Never claim an invented production incident, role, or outcome as your experience.'],
              qa: [['What if a project did not succeed?', 'Explain the original decision and available evidence, what failed, how you detected it, your response, and the change you made afterward. A specific learning story is stronger than a fabricated success.'], ['How do I answer a disagreement question?', 'Describe the shared goal, the competing technical arguments, evidence you gathered, how the decision was made, and how you supported or revisited it. Avoid portraying colleagues as incompetent or revealing confidential details.']],
              exercise: ['Convert a vague claim into a defensible story.', 'Replace "I improved performance a lot" with the measured workload, baseline and comparison method, your exact change, observed result, caveats, and rollback or follow-up. Leave unknown figures as unknown rather than inventing percentages.'] },
            { id: 'mocks', title: 'Mock Scorecards and Readiness Gates',
              notes: ['Score mocks on clarification, correctness, complexity, implementation quality, testing, communication, and response to feedback. For design, add requirement coverage, failure handling, and trade-off depth.', 'After each mock, choose one concrete correction and verify it in the next practice session. A readiness gate might be several recent unseen medium problems solved independently with clear tests and explanation, plus role-appropriate design mocks; it is not a pass-rate guarantee.'],
              qa: [['How many questions are enough?', 'There is no universal number. Evidence of transfer to unseen problems, consistent correctness, and strong explanation matters more than a completed sheet. Use counts as coverage indicators, not proof of interview readiness.'], ['Should I repeat failed mocks?', 'Yes, but do not confuse recalling the answer with improvement. Repeat the failing skill on a different problem or altered requirement and compare the same scorecard dimensions.']],
              exercise: ['A candidate solves correctly but never discusses tests. What is the next intervention?', 'Reserve a visible test checklist and practice verbalizing boundary cases before declaring completion. In the next mock, score testing separately from algorithm correctness and verify at least one adversarial example.'] },
            { id: 'final-week', title: 'Final-Week Revision and Interview-Day Practice',
              notes: ['Confirm timezone, meeting links, allowed tools, coding environment, and any accommodations. Practice once with the actual collaboration format where possible. Keep notes for logistics, not unauthorized assistance during an assessment.', 'Reduce the amount of new material near the interview. Review recurring mistakes, rehearse concise project explanations, and preserve sleep and recovery. After the interview, capture your own learning without collecting or sharing confidential question content.'],
              qa: [['What if I freeze during a problem?', 'Restate the goal, trace a tiny example, write a correct baseline, and identify the bottleneck. Explain your thinking and ask a useful clarification. Do not manufacture confidence or remain silent indefinitely.'], ['What should I ask the interviewer?', 'Ask about the team mission, success expectations, technical trade-offs, reliability ownership, and how engineers learn. Tailor questions to the actual role rather than asking for confidential information.']],
              exercise: ['Write a final 48-hour checklist.', 'Verify logistics and environment, review your error log and two relevant designs, rehearse a few truthful stories, prepare thoughtful questions, and stop intensive practice early enough to rest.'] }
        ],
        assessment: { prompt: 'Run a mock loop: one unseen coding problem, one role-relevant design, and two behavioral questions. Use an independent reviewer where possible.', rubric: ['A correct implementation with boundary tests and justified complexity', 'A design with explicit requirements, data flow, consistency choices, and failure recovery', 'Specific personal actions and defensible outcomes in stories', 'A written revision plan tied to observed weaknesses, not just more question counts'] },
        sources: [
            ['Amazon SDE II preparation', 'https://www.amazon.jobs/content/en/how-we-hire/sde-ii-interview-prep'],
            ['Microsoft technical interviews', 'https://careers.microsoft.com/v2/global/en/hiring-tips/technical-interviewing'],
            ['Google hiring overview', 'https://www.google.com/about/careers/applications/how-we-hire/'],
            ['Meta engineering preparation', 'https://www.metacareers.com/careerprograms/preparing-for-your-software-engineering-interview'],
            ['Apple work and team context', 'https://www.apple.com/careers/us/work-at-apple.html'],
            ['Netflix culture', 'https://jobs.netflix.com/culture']
        ]
    },
    {
        id: 'ai-ml', title: 'AI/ML Interview Foundations', price: 49, icon: 'brain',
        summary: 'Interview-focused statistics, model fundamentals, evaluation, leakage prevention, and production reasoning with worked examples.',
        audience: 'SWE-to-ML transitions, early ML engineers, and software engineers facing ML-related interview rounds.',
        prerequisites: 'Basic Python, algebra, probability vocabulary, and comfort reading arrays and tables.',
        outcomes: ['Choose a baseline and evaluation strategy', 'Explain core model and optimization trade-offs', 'Detect leakage and misleading metrics', 'Reason about deployment and model failure'],
        plans: [['Days 1-2', 'Problem framing, baselines, loss functions, and probability. Deliver a one-page classification problem contract.'], ['Days 3-4', 'Metrics, splits, leakage, and regularization. Work through the numeric examples without notes.'], ['Days 5-7', 'Embeddings, experiments, and production diagnosis. Complete a 45-minute ML case discussion.']],
        lessons: [
            { id: 'framing', title: 'Define the Prediction Problem Before the Model',
              notes: ['Specify the decision being supported, prediction unit, label definition, prediction time, and error costs. A model trained on information unavailable at prediction time solves the wrong problem even if its test score is impressive.', 'Compare with a simple heuristic and an appropriate statistical baseline. Establish how performance will change an operational or user outcome before paying for complexity.'],
              qa: [['When should I choose a heuristic rather than ML?', 'When reliable rules already meet the objective, labels are unavailable, the process changes too quickly to learn, or model maintenance costs exceed expected benefit. A baseline also exposes whether a later ML system adds real value.'], ['What is the difference between a label and a business objective?', 'A label is the observable training target, such as a click. The objective may be user satisfaction or retained revenue. A convenient label can be a poor proxy, so evaluate guardrails and downstream effects.']],
              exercise: ['Frame a churn prediction problem without leakage.', 'Define a prediction date, use only features available by that date, and label churn in a future fixed window. Split chronologically and compare against a simple recency baseline. Exclude events from the future label window.'] },
            { id: 'models', title: 'Regression, Logistic Models, and Gradients',
              notes: ['Linear regression predicts a numeric target; logistic regression applies a sigmoid to a linear score for binary probabilities. For logistic loss, the derivative with respect to the logit is predicted probability minus the binary label.', 'Feature scaling affects optimization and regularization. A learning rate that is too large can oscillate or diverge; a very small one may converge too slowly. Inspect loss and validation behavior rather than choosing a model by name.'],
              qa: [['Why is logistic regression still called regression?', 'It models a linear relationship in log-odds, then converts it to a probability. The classification decision additionally requires a threshold chosen for the objective and error costs.'], ['How do I distinguish optimization failure from overfitting?', 'Optimization failure often produces poor training performance or unstable loss. Overfitting typically shows improved training fit while validation performance worsens. Learning curves and a small-data sanity test help separate them.']],
              exercise: ['Interpret a positive logistic-loss gradient when the true label is zero.', 'If the prediction probability is positive and the label is zero, the logit gradient is positive. Gradient descent subtracts it, reducing the score and predicted probability, which is the correct direction.'],
              code: { language: 'python', body: `import math

def stable_sigmoid(logit):
    if logit >= 0:
        return 1.0 / (1.0 + math.exp(-logit))
    exponent = math.exp(logit)
    return exponent / (1.0 + exponent)`, tests: ['assert stable_sigmoid(0) == 0.5', 'assert stable_sigmoid(1000) == 1.0', 'assert stable_sigmoid(-1000) == 0.0'] } },
            { id: 'metrics', title: 'Imbalance, Thresholds, and Calibration',
              notes: ['Accuracy can hide failure on rare events. Precision is TP/(TP+FP); recall is TP/(TP+FN). F1 is their harmonic mean, but it still does not encode every business cost.', 'A ranking metric, threshold metric, and calibration metric answer different questions. Select a threshold on validation data, then evaluate once on an untouched test set. A calibrated probability is especially useful when decisions depend on expected cost.'],
              qa: [['With 80 true positives, 120 false positives, and 20 false negatives, what are precision and recall?', 'Precision is 80/200 = 0.40. Recall is 80/100 = 0.80. F1 is approximately 0.533. High recall here does not imply a low operational false-positive burden.'], ['Why can a high ROC-AUC be insufficient for rare-event detection?', 'ROC-AUC measures ranking over false-positive rates, but a small false-positive rate can still create many false alarms when negatives dominate. Inspect precision-recall behavior, absolute volumes, and the actual operating threshold.']],
              exercise: ['Choose a metric for a human review queue with capacity for 500 alerts/day.', 'Evaluate precision and recall at the capacity-constrained top 500, alert volume stability, and the cost of misses. Do not optimize unconstrained recall while sending a queue the team cannot process.'] },
            { id: 'leakage', title: 'Splits, Cross-Validation, and Data Leakage',
              notes: ['Split according to how the system will generalize: random independent examples, unseen entities, or future time periods. Keep the final test set isolated from feature selection, hyperparameter tuning, and threshold selection.', 'Fit preprocessing only on training folds. Use a pipeline so imputers, scalers, feature selectors, and estimators follow the same boundary. For grouped or temporal data, a random row split can leak entity identity or future information.'],
              qa: [['Is scaling on the complete dataset before splitting safe?', 'No. Even without labels, the test distribution influences fitted preprocessing. Fit scaling on the training split or inside each training fold, then apply the learned transform to validation and test data.'], ['Why does cross-validation not automatically prevent leakage?', 'The split strategy or preprocessing may already leak information. A pipeline cannot fix features computed using future outcomes, and ordinary folds cannot fix repeated users distributed across train and validation when user-level generalization is required.']],
              exercise: ['Diagnose near-perfect fraud accuracy that collapses after deployment.', 'Check whether chargeback status, post-investigation attributes, duplicate transactions, or future aggregates entered the features. Rebuild point-in-time features and temporal validation before increasing model complexity.'] },
            { id: 'generalization', title: 'Bias, Variance, Regularization, and Trees',
              notes: ['Use training and validation curves to diagnose underfitting versus overfitting. More capacity can reduce approximation bias while increasing sensitivity to noise; more data can improve variance but will not repair a mislabeled objective.', 'Regularization constrains fit. L2 penalizes large weights; L1 can encourage sparse coefficients. Tree ensembles capture nonlinear interactions, but still require valid splits, tuning, and careful treatment of missing and categorical data.'],
              qa: [['What is the difference between bagging and boosting?', 'Bagging combines models trained on resampled data, primarily reducing variance. Boosting builds models sequentially to improve the ensemble objective, often reducing bias as well, but may be sensitive to noise and tuning.'], ['Does regularization always improve test performance?', 'No. Too much regularization underfits. Select strength using valid validation data, then examine performance by cohort and not only a global average.']],
              exercise: ['Training error is low while validation error rises as trees get deeper. What would you try?', 'Constrain depth or leaf sizes, tune ensemble regularization and early stopping on validation data, inspect leakage and drift, and compare with a simpler baseline. Do not use the test set to repeatedly choose the winning depth.'] },
            { id: 'embeddings', title: 'Embeddings, Attention, and Adaptation',
              notes: ['Embeddings represent inputs as vectors whose useful geometry depends on training. Cosine similarity compares direction; dot products additionally depend on magnitude unless vectors are normalized.', 'Attention forms weighted combinations of value representations based on query-key compatibility. A larger context window does not guarantee correct retrieval or reasoning. Fine-tuning changes model behavior, whereas retrieval supplies external context at inference time.'],
              qa: [['Can embeddings from different models be compared directly?', 'Generally no. Matching dimensions do not imply a shared coordinate system or similarity meaning. Version embeddings and re-index when changing models, with an explicit migration plan.'], ['When would you fine-tune rather than add retrieval?', 'Fine-tuning can help a stable task format, style, or domain behavior when training data and evaluation support it. Frequently changing factual knowledge and access-controlled documents usually require retrieval or another external data source.']],
              exercise: ['Two normalized vectors have dot product 0.8. What does that tell you?', 'Their cosine similarity is 0.8, but the value is not a calibrated probability of semantic equivalence. Its usefulness depends on the embedding model, domain, and evaluated decision threshold.'] },
            { id: 'experiments', title: 'Experiments, Uncertainty, and Error Analysis',
              notes: ['Version datasets, code, features, hyperparameters, and evaluation. Compare models on the same valid split and examine error slices such as new users, sparse histories, languages, or regions when relevant.', 'Offline improvement is a hypothesis about online value, not proof. Define the randomization unit, primary metric, guardrails, sample-size assumptions, and analysis plan before an A/B test. Avoid repeatedly peeking until a favorable result appears.'],
              qa: [['Why might offline lift disappear online?', 'The offline dataset may be biased, features may be unavailable or delayed, the serving model may differ, or the metric may not represent the user outcome. Latency and feedback loops can also change behavior.'], ['How do I interpret a confidence interval spanning no improvement?', 'The experiment does not provide strong evidence for a directional improvement at the chosen confidence level. It does not prove the models are identical. Check power, effect size, and pre-specified decision rules.']],
              exercise: ['A model improves overall accuracy but harms a small important cohort. What should the review contain?', 'Report cohort sample sizes and uncertainty, the nature and cost of the errors, likely causes, and mitigation options. Do not hide the regression in the average or automatically assume a noisy slice is a real effect without investigation.'] },
            { id: 'production', title: 'Production ML and the Final Interview Case',
              notes: ['Separate data collection, labeling, feature generation, training, model registration, serving, and monitoring. Define how each stage recovers from failure and which versions are used together.', 'Monitor input changes, feature freshness, service latency, and outcomes once labels mature. Retraining is not the only response to drift: upstream data bugs, policy changes, or serving skew may require a different fix.'],
              qa: [['What is training-serving skew?', 'It is a mismatch between features, transforms, or behavior used during training and those used in production. Shared transformation logic, versioning, point-in-time joins, and comparison monitoring reduce the risk.'], ['What should happen if the feature store is unavailable?', 'Use a defined fallback such as recent safe features or a simpler baseline when the product permits it. Fail explicitly when a fallback would violate safety or correctness. Measure fallback rates and restore the full path deliberately.']],
              exercise: ['Present a fraud-model deployment plan.', 'Specify prediction time, label delay, class imbalance, valid splits, queue capacity, baseline and threshold, shadow/canary rollout, model and feature versions, human-review integration, and rollback. Explain why each metric supports a business decision.'] }
        ],
        assessment: { prompt: 'Frame and defend an ML solution for a rare-event classification problem with delayed labels and a bounded review queue.', rubric: ['Prediction-time feature and label contract', 'Valid temporal/entity split and leakage prevention', 'Metrics and threshold tied to review capacity and error costs', 'Baseline, rollout, monitoring, and recovery plan'] },
        sources: [['Google Machine Learning Crash Course', 'https://developers.google.com/machine-learning/crash-course'], ['scikit-learn common pitfalls', 'https://scikit-learn.org/stable/common_pitfalls.html'], ['Rules of Machine Learning', 'https://developers.google.com/machine-learning/guides/rules-of-ml']]
    },
    {
        id: 'rag', title: 'RAG and LLM Engineering Interviews', price: 49, icon: 'search',
        summary: 'Retrieval, chunking, hybrid search, evaluation, access control, agent workflows, and production trade-offs for LLM engineering interviews.',
        audience: 'AI application engineers, backend engineers building assistants, and candidates for LLM/RAG platform roles.',
        prerequisites: 'Basic APIs, databases, Python, and familiarity with embeddings and language-model inference.',
        outcomes: ['Design a versioned retrieval pipeline', 'Evaluate retrieval separately from generation', 'Handle tenant isolation and prompt injection boundaries', 'Explain latency, cost, agents, and failure recovery'],
        plans: [['Days 1-2', 'Frame the use case and build an ingestion/retrieval design. Define answerability and permissions.'], ['Days 3-4', 'Work through hybrid search, ranking, and evaluation examples. Create an error taxonomy.'], ['Days 5-7', 'Add security boundaries, failure handling, and an interview-ready project narrative with measurable results.']],
        lessons: [
            { id: 'architecture', title: 'RAG, Fine-Tuning, and the Problem Contract',
              notes: ['RAG retrieves external evidence and supplies it to a model at answer time. It can improve grounding and freshness, but does not eliminate hallucinations or automatically enforce access control.', 'Define the users, source documents, allowed actions, freshness needs, latency, and abstention behavior. A question-answering assistant and a tool-using agent have different risks and recovery requirements.'],
              qa: [['Why not put all documents in a large prompt?', 'Context limits, latency, cost, attention quality, and document permissions make indiscriminate inclusion a poor default. Retrieval selects relevant evidence, but must itself be evaluated and authorized.'], ['Does fine-tuning replace a RAG index?', 'Not generally for changing facts or per-user access-controlled data. Fine-tuning can improve behavior, formatting, or task competence; retrieval provides selected external knowledge. They may be combined for a measured reason.']],
              exercise: ['Design the minimum viable architecture for an internal policy assistant.', 'Use versioned document ingestion, permission-aware retrieval, a bounded context builder, a model gateway, citations, abstention, and evaluation logs with appropriate redaction. Start without autonomous tools unless the use case requires actions.'] },
            { id: 'ingestion', title: 'Chunking, Versioning, and Freshness',
              notes: ['Parse structure before choosing chunk boundaries. Headings, tables, lists, and code often need different treatment. Preserve source IDs, section paths, version, tenant, and permissions alongside each chunk.', 'Evaluate chunk size and overlap against retrieval and answer quality. Small chunks can lose context; large chunks can dilute relevance and increase cost. Stable chunk identities and tombstones make updates and deletions traceable.'],
              qa: [['What is the best universal chunk size?', 'There is none. Test representative document types and queries, measure retrieval recall and grounded answer quality, and include storage and latency cost. Token limits alone do not define a good semantic boundary.'], ['How do you change an embedding model?', 'Create a versioned parallel index, regenerate embeddings with the new model, evaluate representative queries, shift traffic gradually, and retain rollback until the new path is validated. Never mix incompatible vectors in one similarity space.']],
              exercise: ['A table loses its headers during extraction. What failures should you expect?', 'Values may retrieve without their units or column meaning, leading to confident but incorrect answers. Preserve table structure or attach header context to chunks, then add queries that require interpreting the affected columns.'] },
            { id: 'retrieval', title: 'Hybrid Retrieval and Reranking',
              notes: ['Lexical retrieval is useful for exact identifiers, names, and rare terms. Dense retrieval can improve semantic matching. Hybrid systems combine candidate sets before deduplication, filtering, and optional reranking.', 'Reciprocal rank fusion combines ranks rather than pretending lexical and vector scores are directly comparable. A reranker can improve ordering but adds latency and needs its own evaluation.'],
              qa: [['Why can dense search miss an exact product code?', 'The embedding may not preserve exact token identity strongly enough. A lexical field or exact filter provides the appropriate signal; semantic similarity should not replace deterministic identifiers.'], ['Why filter permissions before reranking?', 'Unauthorized passages must not reach a reranker or downstream model. Apply tenant and access constraints before retrieval when possible and recheck current authorization before building the final context.']],
              exercise: ['Combine two retrieval lists without directly adding incompatible scores.', 'Use rank fusion with a documented constant, deduplicate document IDs, and evaluate recall and ranking on a labeled set. Then compare the improvement and latency cost of a reranker.'],
              code: { language: 'python', body: `def reciprocal_rank_fusion(rankings, offset=60):
    scores = {}
    for ranking in rankings:
        unique = list(dict.fromkeys(ranking))
        for rank, document_id in enumerate(unique, start=1):
            scores[document_id] = scores.get(document_id, 0.0) + 1.0 / (offset + rank)
    return sorted(scores, key=lambda document_id: (-scores[document_id], document_id))`, tests: ['assert reciprocal_rank_fusion([["a", "b"], ["b", "c"]]) == ["b", "a", "c"]', 'assert reciprocal_rank_fusion([]) == []', 'assert reciprocal_rank_fusion([["a", "a", "b"]]) == ["a", "b"]'] } },
            { id: 'evaluation', title: 'Evaluate Retrieval and Answer Quality Separately',
              notes: ['Build a versioned evaluation set with representative answerable, unanswerable, ambiguous, and access-restricted queries. Include expected evidence when possible, not just a reference answer string.', 'Measure retrieval recall and ranking separately from groundedness, completeness, citation support, refusal behavior, latency, and cost. Model-based judges are useful signals but need calibration against human review.'],
              qa: [['The answer is wrong. How do you locate the failure?', 'First check whether relevant evidence exists and was retrieved. Then inspect filtering, reranking, truncation, prompt construction, and generation. A retrieval failure and a model failure need different remedies.'], ['Does matching a reference answer prove correctness?', 'No. The reference may be incomplete, and different wording can be correct. Check claims against evidence, account for acceptable alternatives, and review uncertain or high-impact cases.']],
              exercise: ['A query has four known relevant documents, and two appear in the top five results. What is recall@5?', 'Recall@5 is 2/4 = 0.5. Precision@5 is 2/5 = 0.4 if all five results are distinct and relevance labels are complete. Neither metric alone proves a correct final answer.'] },
            { id: 'security', title: 'Access Control and Untrusted Document Instructions',
              notes: ['Treat retrieved content as data, not authority. A document cannot grant tool permissions, change a system policy, or authorize sending information elsewhere. Tool actions require explicit application-level permission and, where appropriate, human approval.', 'Enforce tenant isolation and current document authorization before sending context to a model. Cache keys and cache eligibility must account for user or policy scope, source versions, and privacy requirements.'],
              qa: [['Can a system prompt alone enforce document permissions?', 'No. Authorization belongs in the application and storage boundaries. The model should never receive a private passage the user is not allowed to access, regardless of instructions asking it not to reveal it.'], ['What happens after access is revoked?', 'Block the source at the authoritative read boundary immediately, invalidate eligible caches, propagate index changes, and apply deletion/retention rules to text, vectors, and traces. Already delivered text cannot be retroactively made unread.']],
              exercise: ['A retrieved page says to email the conversation to an external address. What should the application do?', 'Treat the instruction as untrusted document content. Do not execute it. Continue only with the authorized user task and independently permitted tools, and test this behavior as part of the regression suite.'] },
            { id: 'serving', title: 'Latency, Cost, Streaming, and Reliability',
              notes: ['Break the latency budget into retrieval, reranking, context assembly, queueing, first token, and generation. Optimize the slow stage with measurements rather than assuming the largest model is always the bottleneck.', 'Use bounded input and output tokens, request cancellation, provider quotas, timeout budgets, and explicit fallback behavior. A slow client should not create an unbounded streaming buffer.'],
              qa: [['Can you retry a partially streamed response transparently?', 'Not safely in general. A new generation can diverge, duplicate text, and incur additional cost. Signal an incomplete result or use a deliberately designed resumable protocol; do not silently splice unrelated completions.'], ['When is a semantic response cache unsafe?', 'When similar wording has different permissions, time-sensitive facts, personalization, or other context. Similarity is not sufficient cache eligibility. Use tenant/policy/source/model/prompt versions and reject unsuitable requests.']],
              exercise: ['Reduce cost without sacrificing measured answer quality.', 'First remove redundant retrieved context, bound output length, and route suitable tasks to an evaluated smaller model. Compare quality and failure rates on the same dataset before accepting savings.'] },
            { id: 'agents', title: 'Tool-Using Agents and Durable Workflows',
              notes: ['An agent needs explicit tool schemas, validation, scoped permissions, execution budgets, and a durable record of actions. A loop that keeps asking a model what to do is not an operationally complete workflow.', 'Checkpoint state around side effects, preserve idempotency keys, and distinguish retryable reads from irreversible operations. Require appropriate approval for payments, external communication, or destructive changes.'],
              qa: [['How do you avoid performing a payment twice after a worker crash?', 'Persist a stable operation identity before the external call, use provider idempotency where supported, and reconcile ambiguous results before retrying. A model-generated plan is not a transaction log.'], ['When should you avoid an agent?', 'When a deterministic pipeline already solves the task reliably, or when actions cannot be sufficiently constrained and evaluated. Add dynamic planning only when its flexibility justifies extra cost, latency, and risk.']],
              exercise: ['Design recovery after a tool completed but its result was not checkpointed.', 'Resume from the durable operation record and query the tool/provider status using the original identity. Reconcile the outcome, then checkpoint it. Do not generate a fresh operation and blindly repeat the side effect.'] },
            { id: 'project', title: 'Present an Interview-Ready RAG Project',
              notes: ['Describe the user problem, document constraints, baseline, chosen architecture, evaluation set, measured results, and known limitations. A framework diagram without evidence of quality is not enough.', 'Show one retrieval failure, one generation failure, and one permission or freshness failure, then explain the corresponding fixes and regression tests. Keep source data and evaluation examples appropriate to share.'],
              qa: [['What makes a RAG demo credible in an interview?', 'Reproducible evaluation, versioned sources and prompts, a clear failure taxonomy, latency and cost measurements, and an honest explanation of limitations. A polished chat box alone proves little about retrieval quality.'], ['How should you answer an unknown technical follow-up?', 'State what you know, identify the uncertain assumption, and describe a targeted experiment or reference you would use. Do not fabricate benchmark numbers or claim a framework provides guarantees you have not verified.']],
              exercise: ['Run a 45-minute design mock for a multi-tenant document assistant.', 'Spend time on requirements and permissions, ingestion/versioning, hybrid retrieval, context checks, evaluation, latency/cost, and failure recovery. Include an unanswerable query and an access-revocation scenario in the final walkthrough.'] }
        ],
        assessment: { prompt: 'Design an enterprise assistant with document updates, revocations, mixed lexical/semantic queries, and a bounded latency/cost budget.', rubric: ['Clear ingestion and versioning contract', 'Permission-aware retrieval and final context authorization', 'Separate retrieval and generation evaluation', 'Explicit streaming, cancellation, fallback, and deletion behavior'] },
        sources: [['Azure RAG design and evaluation', 'https://learn.microsoft.com/en-us/azure/architecture/ai-ml/guide/rag/rag-solution-design-and-evaluation-guide'], ['Google ML embeddings', 'https://developers.google.com/machine-learning/crash-course/embeddings'], ['Azure AI architecture', 'https://learn.microsoft.com/en-us/azure/architecture/ai-ml/']]
    },
    {
        id: 'ml-system-design', title: 'ML System Design Interviews', price: 49, icon: 'workflow',
        summary: 'End-to-end ML design for recommendations, ads, fraud, search, forecasting, feature platforms, and safe production rollout.',
        audience: 'ML engineers and experienced software engineers preparing for ML platform or applied-ML design rounds.',
        prerequisites: 'Core ML metrics and validation, basic distributed systems, APIs, and data pipelines.',
        outcomes: ['Connect business objectives to labels and serving decisions', 'Design retrieval/ranking and real-time scoring systems', 'Use point-in-time features and valid evaluation', 'Discuss capacity, cold start, drift, and rollback'],
        plans: [['Days 1-2', 'Practice the delivery framework and recommendation design, including label and feature contracts.'], ['Days 3-4', 'Compare advertising, fraud, search, and forecasting objectives and evaluation.'], ['Days 5-7', 'Deep-dive feature platforms, serving, experiments, and one complete timed design mock.']],
        lessons: [
            { id: 'framework', title: 'An End-to-End ML Design Framework',
              notes: ['Translate the product objective into a prediction task, decision point, label window, data contract, and evaluation plan. Establish a simple baseline before describing model architecture.', 'Walk through collection, training data, features, model training, validation, registry, serving, feedback, and monitoring. Explain the offline and online paths separately and show where their contracts meet.'],
              qa: [['What should come before choosing a neural architecture?', 'The objective, data availability, label definition, timing, error costs, baseline, and serving constraints. Without them, a model choice is difficult to justify or evaluate.'], ['How does ML design differ from ordinary service design?', 'It includes service reliability and scaling, but also data quality, delayed or biased labels, changing distributions, evaluation uncertainty, and feedback loops. Both systems and statistical reasoning are required.']],
              exercise: ['Define the contract for a real-time purchase-risk score.', 'Specify what event triggers scoring, which features exist at that instant, the future outcome used as a label, acceptable latency, how the score changes a decision, and how false positives and misses are handled.'] },
            { id: 'recommendations', title: 'Candidate Retrieval and Personalized Ranking',
              notes: ['A large catalogue usually needs a two-stage approach: inexpensive candidate retrieval followed by a more expensive ranker over a bounded set. Include popularity, content, and personalized candidate sources where appropriate.', 'Log exposures, positions, and interactions so training data reflects what users could actually see. Add cold-start behavior for users and items, eligibility filters, and diversity or product guardrails.'],
              qa: [['Why not score every item with the best model?', 'The full catalogue may exceed latency and compute budgets. Candidate retrieval limits work, but its recall becomes an upper bound on what the ranker can recover. Evaluate both stages.'], ['How do you avoid a feedback loop that only recommends already popular items?', 'Use controlled exploration, monitor coverage and cohort outcomes, and account for exposure bias in evaluation and training when feasible. Blindly reinforcing observed clicks can reduce discovery.']],
              exercise: ['Design a cold-start fallback.', 'Use eligible popularity and content features, optionally explicit user preferences, with measured exploration. Separate cold-start cohorts in evaluation and gradually transition to personalized signals as reliable history accumulates.'] },
            { id: 'advertising', title: 'CTR, Conversion, and Delayed Labels',
              notes: ['Ad ranking may combine predicted response, value, and product or auction rules. Probability calibration matters when predictions are used in expected-value calculations, not only ordering.', 'Conversions arrive after impressions and clicks. Define attribution and label maturity, deduplicate events, and avoid treating every recent unconverted example as a final negative.'],
              qa: [['Why can a good AUC model still produce poor expected-revenue decisions?', 'AUC assesses ranking, not probability calibration. Overconfident probabilities can distort value estimates even when pairwise ranking is good. Evaluate calibration and the actual decision metric.'], ['How do you handle delayed conversions in evaluation?', 'Use a defined observation window and mature labels, or a deliberately modeled delay process. Report censoring and label maturity rather than silently treating missing outcomes as negatives.']],
              exercise: ['An updated model raises clicks but lowers downstream conversions. What do you investigate?', 'Check objective mismatch, calibration, traffic allocation, attribution, delayed-label maturity, and changes in the shown population. Use the pre-specified experiment metrics and guardrails before concluding the model improved.'] },
            { id: 'fraud', title: 'Fraud Detection and Review Capacity',
              notes: ['Fraud detection combines severe imbalance, delayed labels, adversarial adaptation, and costly false positives. Frame the operating point around the action taken, not just a model score.', 'Use features available at transaction time and temporal backtesting. Track latency, manual-review capacity, false-positive burden, and the process that generates labels, including investigation bias.'],
              qa: [['Why is random train/test splitting risky here?', 'Repeated entities, future aggregations, and investigation outcomes can leak across the split. Temporal and sometimes entity-aware separation better reflect deployment, depending on the target generalization.'], ['What fallback is appropriate if the model service fails?', 'It depends on risk and business policy: rules, step-up verification, a bounded review path, or explicit rejection may be options. The choice must be agreed in advance and monitored, not invented during an outage.']],
              exercise: ['Design a threshold policy with limited reviewers.', 'Evaluate precision and recall at the allowed alert volume, separate high-risk automatic actions from review decisions, and monitor queue age and cohort impacts. Tune thresholds on validation data rather than the final test set.'] },
            { id: 'search', title: 'Learning to Rank and Search Evaluation',
              notes: ['Search must combine query understanding, lexical and semantic retrieval, eligibility filtering, and ranking. Query intent and document freshness can change what relevance means.', 'NDCG rewards relevant results near the top and normalizes against an ideal ordering. Its meaning depends on the grading scheme and labeled candidate set; incomplete labels and click-position bias still require care.'],
              qa: [['Why evaluate retrieval recall before NDCG?', 'A ranker cannot surface a relevant document missing from the candidates. Diagnose candidate coverage separately from ordering quality to avoid optimizing the wrong stage.'], ['Are clicks clean relevance labels?', 'No. Clicks depend on position, presentation, exposure, and user intent, and may not imply satisfaction. Use careful logging and appropriate evaluation or debiasing methods rather than equating all clicks with ground truth.']],
              exercise: ['A ranker improves NDCG offline but hurts rare queries online. What next?', 'Inspect query slices, candidate recall, label coverage, freshness, feature availability, and latency. A large head-query improvement can hide tail-query regressions.'],
              code: { language: 'python', body: `import math

def ndcg_at_k(relevances, limit):
    if limit <= 0:
        return 0.0
    def dcg(values):
        return sum((2 ** relevance - 1) / math.log2(rank + 2) for rank, relevance in enumerate(values))
    ideal = dcg(sorted(relevances, reverse=True)[:limit])
    return dcg(relevances[:limit]) / ideal if ideal else 0.0`, tests: ['assert ndcg_at_k([3, 2, 1], 3) == 1.0', 'assert ndcg_at_k([0, 0], 2) == 0.0', 'assert 0 < ndcg_at_k([0, 3, 1], 3) < 1'] } },
            { id: 'forecasting', title: 'Forecasting and Temporal Validation',
              notes: ['Define forecast horizon, granularity, update cadence, and the action driven by the forecast. Compare with seasonal and recent-value baselines before using a complex model.', 'Use rolling-origin backtesting and only data available at each forecast time. Evaluate appropriate horizons and cohorts. Prediction intervals describe uncertainty more usefully than a single point when inventory or staffing decisions depend on risk.'],
              qa: [['Why can a random split overstate forecasting quality?', 'Future observations can influence training for earlier forecast targets, and adjacent windows may be highly dependent. A chronological evaluation better matches the real prediction boundary.'], ['Is MAPE always appropriate?', 'No. It is unstable or undefined when actual values are zero and can overweight small denominators. Choose metrics that match the scale and decision, such as MAE, RMSE, scaled errors, or quantile losses when appropriate.']],
              exercise: ['Design a demand-forecast backtest.', 'Choose historical forecast origins, train only on prior data, forecast the same horizon used in production, compare with a seasonal baseline, and report errors and interval coverage by product and demand level.'] },
            { id: 'feature-platform', title: 'Point-in-Time Features and Serving Contracts',
              notes: ['A feature value needs an entity key, event time, availability time, version, and freshness policy. Point-in-time training joins must respect when the feature was actually available, not just the timestamp of the underlying event.', 'Online and offline stores serve different latency and history needs. Share transformation definitions where possible, version them, and monitor skew and staleness. Keep a model registry with compatibility and rollback information.'],
              qa: [['What is wrong with joining every training row to the latest customer aggregate?', 'The latest aggregate may include future behavior relative to that row prediction time. This leaks information and produces an unrealistically easy training and evaluation problem.'], ['How do you deploy a model that requires a new feature?', 'Deploy and backfill the feature path, validate availability and distributions, test compatibility, then roll out the model gradually. Preserve the old model and feature contract for rollback until the new path is stable.']],
              exercise: ['Describe a feature-store outage plan.', 'Specify bounded stale reads or a simpler model only where the product permits them, monitor fallback and freshness, enforce required-feature policies, and restore traffic gradually after validating the recovered data path.'] },
            { id: 'operations', title: 'Experiments, Monitoring, and Incident Reasoning',
              notes: ['Use offline evaluation, shadow traffic when appropriate, canary release, and controlled experiments. Decide the primary metric, guardrails, randomization unit, and rollback criteria before launch.', 'Monitor data contracts, model outputs, service behavior, and delayed business outcomes. A distribution alert is a signal to investigate, not an automatic instruction to retrain. Upstream bugs and policy changes require different responses.'],
              qa: [['What evidence would justify rolling back a model?', 'A reproducible correctness or policy violation, breached latency or availability budgets, or statistically and operationally meaningful guardrail regression under the agreed plan. Keep enough versioned evidence to distinguish model issues from data or serving failures.'], ['Can a model be healthy while the ML system is failing?', 'Yes. Feature latency, stale joins, missing labels, queue backlogs, and broken experiment assignment can harm the product even when model weights and offline metrics are unchanged.']],
              exercise: ['Run a complete design mock for recommendations or fraud.', 'State the objective, labels, baseline, data and feature boundaries, training/evaluation, serving budget, fallbacks, experiments, and monitoring. Finish with a concrete failure scenario and the evidence needed to diagnose it.'] }
        ],
        assessment: { prompt: 'Design one ML product end to end, then handle a feature outage, a delayed-label issue, and an offline/online metric disagreement.', rubric: ['Objective and labels match a real decision', 'Valid data and feature timing boundaries', 'Serving architecture fits stated capacity and latency', 'Evaluation, rollout, cold start, monitoring, and rollback are explicit'] },
        sources: [['Google recommendation systems', 'https://developers.google.com/machine-learning/recommendation'], ['Rules of Machine Learning', 'https://developers.google.com/machine-learning/guides/rules-of-ml'], ['Azure ML architecture guidance', 'https://learn.microsoft.com/en-us/azure/architecture/ai-ml/']]
    },
    {
        id: 'sql-data', title: 'SQL and Data Interview Practice', price: 49, icon: 'database',
        summary: 'Solved SQL exercises and interview reasoning for joins, ranking, deduplication, windows, retention, funnels, NULLs, and query design.',
        audience: 'Backend, data engineering, analytics, and ML candidates who need reliable SQL under interview constraints.',
        prerequisites: 'Basic SELECT, WHERE, GROUP BY, and familiarity with rows, keys, and joins.',
        outcomes: ['Define row grain before joining', 'Use window functions and explicit tie rules', 'Handle NULLs, duplicates, and temporal boundaries', 'Explain performance and transaction trade-offs'],
        plans: [['Days 1-2', 'Practice row grain, joins, ranking, and deterministic deduplication using the supplied examples.'], ['Days 3-4', 'Work through running totals, funnels, retention, and consecutive activity.'], ['Days 5-7', 'Explain query plans and isolation, then complete unseen SQL variants with edge cases.']],
        lessons: [
            { id: 'grain', title: 'Row Grain, Joins, and Double Counting',
              notes: ['State what one row represents in every input and output. Joining two one-to-many relationships can multiply rows and inflate sums. Pre-aggregate at the intended join grain when needed.', 'Choose INNER or LEFT JOIN according to whether unmatched entities must remain. A predicate on the right table in WHERE can accidentally turn a left join into an inner join.'],
              qa: [['Why did customer revenue double after joining order items and payments?', 'Both tables may have multiple rows per order, producing a many-to-many multiplication. Aggregate each to one row per order before joining, or join only the relationship needed for the requested measure.'], ['Does SELECT DISTINCT fix incorrect aggregation?', 'Not reliably. It may hide duplicate output rows while the aggregate is already inflated, or discard legitimately equal values. Fix the grain and join conditions instead.']],
              exercise: ['Compute customer revenue and payment totals from two order-level child tables.', 'Aggregate items by order_id and payments by order_id independently, join those results to orders, then aggregate by customer. Include unpaid orders if required and use COALESCE only after deciding the intended missing-value meaning.'] },
            { id: 'ranking', title: 'Top N per Group and Tie Semantics',
              notes: ['ROW_NUMBER selects an exact number of rows with deterministic ordering. RANK leaves gaps after ties; DENSE_RANK does not. Ask whether top three means three rows or three distinct score levels.', 'Filter a window result in an outer query or CTE. Window functions logically operate after WHERE, so the same-level WHERE clause cannot normally reference the computed rank.'],
              qa: [['Which function returns employees in the top two distinct salaries per department?', 'DENSE_RANK over department ordered by salary descending, then filter rank <= 2 in an outer query. It can return more than two employees when salaries tie.'], ['How do I select exactly two employees per department?', 'Use ROW_NUMBER with a complete deterministic ordering, such as salary descending then employee ID, and filter row number <= 2. Explain that this resolves ties rather than including all tied employees.']],
              exercise: ['What should happen when three people share the highest salary?', 'For top distinct salary levels, include all three and then the next distinct level. For exactly two rows, apply the explicitly agreed tie-breaker. These are different contracts.'],
              code: { language: 'sql', body: `WITH ranked AS (
    SELECT employee_id, department, salary,
           DENSE_RANK() OVER (
               PARTITION BY department ORDER BY salary DESC
           ) AS salary_rank
    FROM employees
)
SELECT employee_id, department, salary
FROM ranked
WHERE salary_rank <= 2
ORDER BY department, salary DESC, employee_id;`, fixture: "CREATE TABLE employees(employee_id INTEGER, department TEXT, salary INTEGER); INSERT INTO employees VALUES (1,'eng',100),(2,'eng',100),(3,'eng',90),(4,'sales',120),(5,'sales',110),(6,'sales',100);", expected: [[1, 'eng', 100], [2, 'eng', 100], [3, 'eng', 90], [4, 'sales', 120], [5, 'sales', 110]] } },
            { id: 'deduplication', title: 'Latest Record and Deterministic Deduplication',
              notes: ['Define the business key and which version wins. Updated timestamps may tie, so add a deterministic secondary ordering such as a unique ingestion sequence.', 'Do not choose arbitrary non-aggregated columns alongside MAX(updated_at). Select the complete winning row using a window function or a join with a well-defined tie policy.'],
              qa: [['Why can joining back on MAX(updated_at) return multiple rows?', 'Several versions can share the latest timestamp. Without an explicit tie-breaker, the query has not defined a unique winner.'], ['Should an older late-arriving event overwrite a newer version?', 'Usually not when source version or event-time order defines truth. Keep ingestion order separate from business version and document how corrections differ from stale retries.']],
              exercise: ['Deduplicate change records with tied timestamps.', 'Partition by the entity key and order by updated_at descending, then a unique ingestion ID descending. Retain row number one and test two rows with equal timestamps.'],
              code: { language: 'sql', body: `WITH versions AS (
    SELECT entity_id, value, updated_at, ingestion_id,
           ROW_NUMBER() OVER (
               PARTITION BY entity_id
               ORDER BY updated_at DESC, ingestion_id DESC
           ) AS version_rank
    FROM changes
)
SELECT entity_id, value
FROM versions
WHERE version_rank = 1
ORDER BY entity_id;`, fixture: "CREATE TABLE changes(entity_id INTEGER, value TEXT, updated_at TEXT, ingestion_id INTEGER); INSERT INTO changes VALUES (1,'old','2026-01-01',1),(1,'new','2026-01-02',2),(1,'winner','2026-01-02',3),(2,'only','2026-01-01',4);", expected: [[1, 'winner'], [2, 'only']] } },
            { id: 'windows', title: 'Running Totals and Window Frames',
              notes: ['Specify the frame rather than relying on a database default. ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW creates a row-by-row running total with the chosen ordering.', 'Seven preceding rows are not necessarily seven calendar days. Aggregate to the required daily grain and add a calendar spine for missing days, or use the appropriate time-range frame in the chosen SQL dialect.'],
              qa: [['Why can equal sort keys receive the same running total?', 'The default frame in many databases includes peer rows with the same ORDER BY value. Use an explicit ROWS frame and deterministic tie-breaker when the contract requires a row-by-row accumulation.'], ['Should missing days be treated as zero?', 'Only if missing means no activity under the data contract. A missing ingestion batch is not the same as zero business activity. Clarify data completeness before filling gaps.']],
              exercise: ['Calculate a customer running total when timestamps tie.', 'Order by timestamp and a unique order ID, then use an explicit ROWS frame. This gives a deterministic intermediate total for each order.'],
              code: { language: 'sql', body: `SELECT order_id, customer_id,
       SUM(amount_minor) OVER (
           PARTITION BY customer_id
           ORDER BY created_at, order_id
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS running_total
FROM orders
ORDER BY customer_id, created_at, order_id;`, fixture: "CREATE TABLE orders(order_id INTEGER, customer_id INTEGER, created_at TEXT, amount_minor INTEGER); INSERT INTO orders VALUES (1,1,'2026-01-01',100),(2,1,'2026-01-01',200),(3,1,'2026-01-02',50),(4,2,'2026-01-01',25);", expected: [[1, 1, 100], [2, 1, 300], [3, 1, 350], [4, 2, 25]] } },
            { id: 'retention', title: 'Cohorts, Retention, and Ordered Funnels',
              notes: ['Define the cohort event, timezone, return event, and horizon. Day-1 retention is not the same as any return within seven days. Deduplicate user/day activity at the appropriate grain.', 'A funnel needs an entity or session key and event ordering. Users who independently performed all event types have not necessarily completed them in the required sequence or time window.'],
              qa: [['What is the denominator of day-1 retention?', 'The eligible users in the original cohort whose day-1 observation window is complete, according to the chosen definition. Do not include immature cohorts without explaining censoring.'], ['How do repeated funnel events change the query?', 'Choose the first qualifying sequence or another explicit rule within a session/window. Joining every view to every purchase can multiply counts and accept purchases that occurred before the view.']],
              exercise: ['A cohort has 100 users, 30 return the next day, and 50 return at least once during the next week. What are the two metrics?', 'Day-1 retention is 30% if all observation windows are mature. Return-within-week rate is 50% under that separate definition. They should not be labeled as the same retention metric.'] },
            { id: 'islands', title: 'Consecutive Activity and Gaps-and-Islands',
              notes: ['Deduplicate activity dates before detecting consecutive runs. For consecutive integer day numbers, day_number minus row_number is constant within each run.', 'Group by that constant within a user, then count the run length. With real dates, use the equivalent date arithmetic for the SQL dialect and timezone contract.'],
              qa: [['Why must duplicate activity days be removed first?', 'ROW_NUMBER increments for each row, while a repeated day does not advance time. That breaks the constant-difference property and can split or inflate runs.'], ['Can this method detect consecutive business days directly?', 'Not with ordinary calendar day numbers. Map dates to a business-calendar sequence first, then detect runs in that sequence.']],
              exercise: ['Find the longest consecutive run from normalized day numbers.', 'Deduplicate user/day pairs, compute a row number by day within each user, group on day_number minus row_number, and take the maximum run size per user.'],
              code: { language: 'sql', body: `WITH daily AS (
    SELECT DISTINCT user_id, day_number FROM activity
), numbered AS (
    SELECT user_id, day_number,
           day_number - ROW_NUMBER() OVER (
               PARTITION BY user_id ORDER BY day_number
           ) AS island
    FROM daily
), runs AS (
    SELECT user_id, island, COUNT(*) AS run_length
    FROM numbered
    GROUP BY user_id, island
)
SELECT user_id, MAX(run_length)
FROM runs
GROUP BY user_id
ORDER BY user_id;`, fixture: 'CREATE TABLE activity(user_id INTEGER, day_number INTEGER); INSERT INTO activity VALUES (1,1),(1,2),(1,2),(1,3),(1,7),(2,2),(2,4);', expected: [[1, 3], [2, 1]] } },
            { id: 'nulls', title: 'NULLs, Anti-Joins, and Missing Data',
              notes: ['SQL uses three-valued logic. Comparisons with NULL are unknown rather than true or false. Use IS NULL when testing for missingness, and understand how this affects WHERE and NOT IN.', 'COUNT(*) counts rows; COUNT(column) counts non-NULL values. SUM over no matching rows is commonly NULL, so use COALESCE only when zero is the correct semantic result.'],
              qa: [['Why can NOT IN return no customers when the subquery contains NULL?', 'A NULL in the comparison set can make the predicate unknown for otherwise unmatched values. NOT EXISTS with an explicit correlation avoids this common anti-join trap.'], ['Does a NULL amount mean zero revenue?', 'Not necessarily. It may mean unknown, unrecorded, or not applicable. Decide the data contract before replacing it; otherwise an apparently clean report can hide incomplete data.']],
              exercise: ['Return customers with no orders, even if an order has a NULL customer ID.', 'Use a correlated NOT EXISTS comparison on customer ID. An unrelated NULL order does not match a known customer and should not eliminate all results.'],
              code: { language: 'sql', body: `SELECT customer_id
FROM customers AS customer
WHERE NOT EXISTS (
    SELECT 1 FROM orders AS customer_order
    WHERE customer_order.customer_id = customer.customer_id
)
ORDER BY customer_id;`, fixture: 'CREATE TABLE customers(customer_id INTEGER); CREATE TABLE orders(order_id INTEGER, customer_id INTEGER); INSERT INTO customers VALUES (1),(2),(3); INSERT INTO orders VALUES (10,1),(11,NULL);', expected: [[2], [3]] } },
            { id: 'performance', title: 'Query Plans, Indexes, and Transaction Reasoning',
              notes: ['Explain the access path, cardinality, join strategy, sorting, and aggregation cost. Use EXPLAIN and representative data rather than assuming an index guarantees speed.', 'Composite index order should follow the query predicates and ordering needs. Indexes add write and storage cost. Isolation and locking matter when a query participates in a reservation, payment, or state transition.'],
              qa: [['What index might support customer order history ordered by time?', 'An index beginning with customer_id and then created_at, with a deterministic ID when needed, can support filtering and ordered access. Verify the actual query, selectivity, included columns, and plan before declaring it optimal.'], ['Why is SELECT followed by INSERT unsafe for claiming the last seat?', 'Two transactions can both observe availability. Enforce the invariant with a unique constraint and an appropriate transaction, lock, or conditional update. An application-level precheck is not the authoritative concurrency boundary.']],
              exercise: ['Review a slow paginated order-history endpoint.', 'Inspect the plan and actual row counts, ensure predicates can use a suitable index, avoid unnecessary wide-row fetches, consider keyset pagination with stable ordering, and measure write overhead and concurrent behavior.'] }
        ],
        assessment: { prompt: 'Solve a top-N-with-ties query, a deduplication query, and a cohort/funnel problem; then explain one query plan and one concurrency invariant.', rubric: ['Correct grain, join cardinality, and NULL handling', 'Explicit tie, ordering, timezone, and maturity rules', 'Boundary cases including duplicates and missing matches', 'Performance claims supported by a plausible plan and workload'] },
        sources: [['PostgreSQL window functions', 'https://www.postgresql.org/docs/current/tutorial-window.html'], ['PostgreSQL indexes', 'https://www.postgresql.org/docs/current/indexes.html'], ['PostgreSQL transaction isolation', 'https://www.postgresql.org/docs/current/transaction-iso.html']]
    }
];